-- Yu-Gi-Oh! Forbidden Memories verified PostgreSQL database

-- Prepared for Vincent van Driel.  PostgreSQL 17 compatible.
--
-- Definitive ordinary-fusion contract (original USA disc audit, 2026-09-11):
--   * fusion_pairs stores one row per unordered pair, always low card ID first;
--   * result_card_id is the first effective result returned by SLUS-01411's
--     resolver at 0x80019A60, including its 15 observable odd-tail fusions;
--   * primary/secondary category rules are descriptive provenance only and do
--     not override the concrete result in fusion_pairs;
--   * supplied BIN SHA-256:
--     6e22494a45bf50fa2d239cd3819a57163a5f9b91e0365babc3e101509b5c3a7c
--   * decoded 64 KiB fusion table SHA-256:
--     e3dcb2f0846a31915cc54a6cbfb3d83bb8b4e6fd05f88245f39e192cca1947d1


BEGIN;
DROP SCHEMA IF EXISTS yfm CASCADE;
CREATE SCHEMA yfm;
SET search_path = yfm, public;

CREATE TABLE sources (
  source_key text PRIMARY KEY, repository text NOT NULL, url text NOT NULL,
  revision text NOT NULL, role text NOT NULL
);
CREATE TABLE cards (
  card_id smallint PRIMARY KEY CHECK (card_id BETWEEN 1 AND 722),
  card_name text NOT NULL UNIQUE, description text, guardian_star_1 text,
  guardian_star_2 text, level smallint, primary_type text NOT NULL, attribute text,
  attack integer NOT NULL CHECK (attack >= 0), defense integer NOT NULL CHECK (defense >= 0),
  password text, starchip_cost integer, droppable boolean NOT NULL,
  fusible boolean NOT NULL, starter_available boolean NOT NULL
);
CREATE INDEX cards_name_ci_idx ON cards (lower(card_name));
CREATE INDEX cards_primary_type_idx ON cards (primary_type);
CREATE INDEX cards_attack_idx ON cards (attack);

CREATE TABLE categories (
  category_id smallint PRIMARY KEY, category_name text NOT NULL UNIQUE,
  category_kind text NOT NULL CHECK (category_kind IN ('primary','secondary'))
);
CREATE TABLE card_categories (
  card_id smallint NOT NULL REFERENCES cards ON DELETE CASCADE,
  category_id smallint NOT NULL REFERENCES categories ON DELETE CASCADE,
  membership_kind text NOT NULL CHECK (membership_kind IN ('primary','secondary')),
  PRIMARY KEY (card_id, category_id, membership_kind)
);
CREATE INDEX card_categories_category_idx ON card_categories (category_id, card_id);

CREATE TABLE fusion_rules (
  rule_id smallint PRIMARY KEY, rule_kind text NOT NULL CHECK (rule_kind IN ('general','exact')),
  material_1_expression text NOT NULL, material_2_expression text NOT NULL,
  source_order smallint NOT NULL UNIQUE
);
CREATE TABLE general_fusion_rules (
  tier_id smallint PRIMARY KEY, rule_id smallint NOT NULL REFERENCES fusion_rules ON DELETE CASCADE,
  tier_order smallint NOT NULL, result_card_id smallint NOT NULL REFERENCES cards,
  lower_attack_threshold integer, result_attack_threshold integer NOT NULL,
  UNIQUE (rule_id, tier_order)
);
CREATE TABLE exact_fusion_rules (
  rule_id smallint PRIMARY KEY REFERENCES fusion_rules ON DELETE CASCADE,
  result_card_id smallint NOT NULL REFERENCES cards
);
CREATE TABLE rule_index (
  rule_index_id smallint PRIMARY KEY, rule_id smallint NOT NULL REFERENCES fusion_rules ON DELETE CASCADE,
  tier_id smallint REFERENCES general_fusion_rules ON DELETE CASCADE,
  operand_position smallint NOT NULL CHECK (operand_position IN (1,2)),
  operand_expression text NOT NULL,
  operand_kind text NOT NULL CHECK (operand_kind IN ('category','card','set')),
  category_id smallint REFERENCES categories, card_id smallint REFERENCES cards,
  UNIQUE NULLS NOT DISTINCT (rule_id, tier_id, operand_expression)
);
CREATE INDEX rule_index_expression_ci_idx ON rule_index (lower(operand_expression));
CREATE TABLE rule_operand_cards (
  rule_index_id smallint NOT NULL REFERENCES rule_index ON DELETE CASCADE,
  card_id smallint NOT NULL REFERENCES cards ON DELETE CASCADE,
  PRIMARY KEY (rule_index_id, card_id)
);
CREATE INDEX rule_operand_cards_card_idx ON rule_operand_cards (card_id, rule_index_id);

CREATE TABLE fusion_rule_conflicts (
  conflict_id smallint PRIMARY KEY,
  tier_id smallint NOT NULL REFERENCES general_fusion_rules ON DELETE CASCADE,
  precedence_order smallint NOT NULL,
  conflict_result_card_id smallint NOT NULL REFERENCES cards,
  UNIQUE (tier_id, conflict_result_card_id)
);
CREATE TABLE fusion_pairs (
  material_low_id smallint NOT NULL REFERENCES cards,
  material_high_id smallint NOT NULL REFERENCES cards,
  result_card_id smallint NOT NULL REFERENCES cards,
  is_intended boolean NOT NULL, is_glitch boolean NOT NULL,
  PRIMARY KEY (material_low_id, material_high_id),
  CHECK (material_low_id <= material_high_id), CHECK (is_intended <> is_glitch)
);
CREATE INDEX fusion_pairs_high_idx ON fusion_pairs (material_high_id, material_low_id);
CREATE INDEX fusion_pairs_result_idx ON fusion_pairs (result_card_id);
CREATE TABLE fusion_pair_rule_refs (
  pair_rule_ref_id bigserial PRIMARY KEY,
  material_low_id smallint NOT NULL, material_high_id smallint NOT NULL,
  rule_id smallint NOT NULL REFERENCES fusion_rules,
  tier_id smallint REFERENCES general_fusion_rules,
  UNIQUE NULLS NOT DISTINCT (material_low_id, material_high_id, rule_id, tier_id),
  FOREIGN KEY (material_low_id, material_high_id) REFERENCES fusion_pairs ON DELETE CASCADE
);
CREATE TABLE fusion_conflict_pairs (
  tier_id smallint NOT NULL REFERENCES general_fusion_rules ON DELETE CASCADE,
  material_low_id smallint NOT NULL, material_high_id smallint NOT NULL,
  actual_result_card_id smallint NOT NULL REFERENCES cards,
  PRIMARY KEY (tier_id, material_low_id, material_high_id),
  FOREIGN KEY (material_low_id, material_high_id) REFERENCES fusion_pairs ON DELETE CASCADE
);
CREATE TABLE attack_rule_exceptions (
  material_low_id smallint NOT NULL, material_high_id smallint NOT NULL,
  result_card_id smallint NOT NULL REFERENCES cards, reason text NOT NULL,
  is_glitch boolean NOT NULL,
  PRIMARY KEY (material_low_id, material_high_id),
  FOREIGN KEY (material_low_id, material_high_id) REFERENCES fusion_pairs ON DELETE CASCADE
);

CREATE TABLE equip_rules (
  equip_rule_id smallint PRIMARY KEY, equip_card_id smallint NOT NULL UNIQUE REFERENCES cards,
  source_order smallint NOT NULL UNIQUE
);
CREATE TABLE equip_compatibility (
  equip_rule_id smallint NOT NULL REFERENCES equip_rules ON DELETE CASCADE,
  equipped_card_id smallint NOT NULL REFERENCES cards ON DELETE CASCADE,
  PRIMARY KEY (equip_rule_id, equipped_card_id)
);
CREATE INDEX equip_compatibility_card_idx ON equip_compatibility (equipped_card_id, equip_rule_id);

CREATE TABLE metadata_differences (
  difference_id smallserial PRIMARY KEY, subject text NOT NULL,
  verified_value text NOT NULL, disputed_value text, evidence text NOT NULL
);
CREATE TABLE known_disputed_checks (
  check_id smallserial PRIMARY KEY, material_1 text NOT NULL, material_2 text NOT NULL,
  verified_result text, note text NOT NULL
);
CREATE TABLE qa_checks (
  check_name text PRIMARY KEY, expected_value bigint NOT NULL, actual_value bigint NOT NULL,
  passed boolean GENERATED ALWAYS AS (expected_value = actual_value) STORED
);


