CREATE VIEW v_card_category_text AS
SELECT c.card_id, c.card_name,
       string_agg(DISTINCT cat.category_name, ', ' ORDER BY cat.category_name) AS categories
FROM cards c JOIN card_categories cc USING (card_id) JOIN categories cat USING (category_id)
GROUP BY c.card_id, c.card_name;

CREATE VIEW v_card_details AS
SELECT c.*, v.categories FROM cards c JOIN v_card_category_text v USING (card_id);

CREATE VIEW v_fusion_pairs_detailed AS
SELECT fp.material_low_id, a.card_name AS material_low_name,
       fp.material_high_id, b.card_name AS material_high_name,
       fp.result_card_id, r.card_name AS result_name, r.attack AS result_attack,
       fp.is_intended, fp.is_glitch
FROM fusion_pairs fp JOIN cards a ON a.card_id=fp.material_low_id
JOIN cards b ON b.card_id=fp.material_high_id
JOIN cards r ON r.card_id=fp.result_card_id;

-- Canonical global listing: every unordered fusion appears exactly once.
CREATE VIEW v_card_fusion_lookup AS
SELECT fp.material_low_id AS card_id, a.card_name,
       fp.material_high_id AS partner_card_id, b.card_name AS partner_name,
       fp.result_card_id, r.card_name AS result_name, fp.is_intended, fp.is_glitch
FROM fusion_pairs fp JOIN cards a ON a.card_id=fp.material_low_id
JOIN cards b ON b.card_id=fp.material_high_id JOIN cards r ON r.card_id=fp.result_card_id
ORDER BY fp.material_low_id, fp.material_high_id;

CREATE VIEW v_rule_conflict_pairs_detailed AS
SELECT fcp.tier_id, fr.material_1_expression, fr.material_2_expression,
       expected.card_name AS expected_result, a.card_name AS material_1,
       b.card_name AS material_2, actual.card_name AS actual_result
FROM fusion_conflict_pairs fcp
JOIN general_fusion_rules gfr USING (tier_id)
JOIN fusion_rules fr USING (rule_id)
JOIN cards expected ON expected.card_id=gfr.result_card_id
JOIN cards a ON a.card_id=fcp.material_low_id
JOIN cards b ON b.card_id=fcp.material_high_id
JOIN cards actual ON actual.card_id=fcp.actual_result_card_id;

CREATE VIEW v_equip_compatibility_detailed AS
SELECT er.equip_rule_id, e.card_id AS equip_card_id, e.card_name AS equip_card,
       c.card_id AS equipped_card_id, c.card_name AS equipped_card,
       c.primary_type, c.attack, c.defense
FROM equip_compatibility ec JOIN equip_rules er USING (equip_rule_id)
JOIN cards e ON e.card_id=er.equip_card_id
JOIN cards c ON c.card_id=ec.equipped_card_id;

CREATE OR REPLACE FUNCTION find_card_fusions(p_card_name text)
RETURNS TABLE(card_id smallint, card_name text, partner_card_id smallint, partner_name text,
              result_card_id smallint, result_name text, is_intended boolean, is_glitch boolean)
LANGUAGE sql STABLE AS $$
  SELECT q.card_id, q.card_name,
         CASE WHEN q.card_id=fp.material_low_id THEN fp.material_high_id
              ELSE fp.material_low_id END AS partner_card_id,
         CASE WHEN q.card_id=fp.material_low_id THEN high_card.card_name
              ELSE low_card.card_name END AS partner_name,
         fp.result_card_id, result.card_name, fp.is_intended, fp.is_glitch
  FROM cards q
  JOIN fusion_pairs fp
    ON q.card_id IN (fp.material_low_id,fp.material_high_id)
  JOIN cards low_card ON low_card.card_id=fp.material_low_id
  JOIN cards high_card ON high_card.card_id=fp.material_high_id
  JOIN cards result ON result.card_id=fp.result_card_id
  WHERE lower(q.card_name)=lower(p_card_name)
  ORDER BY partner_name, result.card_name;
$$;

CREATE OR REPLACE FUNCTION find_fusion(p_material_1 text, p_material_2 text)
RETURNS TABLE(material_1 text, material_2 text, result_card_id smallint,
              result_name text, is_intended boolean, is_glitch boolean)
LANGUAGE sql STABLE AS $$
  SELECT low_card.card_name, high_card.card_name, fp.result_card_id, r.card_name,
         fp.is_intended, fp.is_glitch
  FROM cards a CROSS JOIN cards b
  JOIN fusion_pairs fp ON fp.material_low_id=LEAST(a.card_id,b.card_id)
   AND fp.material_high_id=GREATEST(a.card_id,b.card_id)
  JOIN cards low_card ON low_card.card_id=fp.material_low_id
  JOIN cards high_card ON high_card.card_id=fp.material_high_id
  JOIN cards r ON r.card_id=fp.result_card_id
  WHERE lower(a.card_name)=lower(p_material_1)
    AND lower(b.card_name)=lower(p_material_2);
$$;

CREATE OR REPLACE FUNCTION find_fusion_by_id(p_material_1_id smallint, p_material_2_id smallint)
RETURNS TABLE(material_low_id smallint, material_low_name text,
              material_high_id smallint, material_high_name text,
              result_card_id smallint, result_name text,
              is_intended boolean, is_glitch boolean)
LANGUAGE sql STABLE AS $$
  SELECT fp.material_low_id, low_card.card_name,
         fp.material_high_id, high_card.card_name,
         fp.result_card_id, result.card_name,
         fp.is_intended, fp.is_glitch
  FROM fusion_pairs fp
  JOIN cards low_card ON low_card.card_id=fp.material_low_id
  JOIN cards high_card ON high_card.card_id=fp.material_high_id
  JOIN cards result ON result.card_id=fp.result_card_id
  WHERE fp.material_low_id=LEAST(p_material_1_id,p_material_2_id)
    AND fp.material_high_id=GREATEST(p_material_1_id,p_material_2_id);
$$;

CREATE OR REPLACE FUNCTION find_category_fusions(p_category text)
RETURNS TABLE(material_1 text, material_2 text, result_name text,
              is_intended boolean, is_glitch boolean)
LANGUAGE sql STABLE AS $$
  WITH chosen AS (
    SELECT category_id FROM categories WHERE lower(category_name)=lower(p_category)
  )
  SELECT a.card_name, b.card_name, r.card_name, fp.is_intended, fp.is_glitch
  FROM fusion_pairs fp JOIN cards a ON a.card_id=fp.material_low_id
  JOIN cards b ON b.card_id=fp.material_high_id
  JOIN cards r ON r.card_id=fp.result_card_id
  WHERE EXISTS (
    SELECT 1 FROM chosen ch JOIN card_categories cc ON cc.category_id=ch.category_id
    WHERE cc.card_id IN (fp.material_low_id,fp.material_high_id)
  )
  ORDER BY a.card_name,b.card_name,r.card_name;
$$;

CREATE OR REPLACE FUNCTION find_category_rules(p_category text)
RETURNS TABLE(rule_id smallint, tier_id smallint, rule_kind text,
              material_1_expression text, material_2_expression text,
              result_name text, indexed_operand text)
LANGUAGE sql STABLE AS $$
  WITH relevant_rule_tiers AS (
    SELECT DISTINCT ri.rule_id, ri.tier_id
    FROM categories cat JOIN card_categories cc USING (category_id)
    JOIN rule_operand_cards roc USING (card_id)
    JOIN rule_index ri USING (rule_index_id)
    WHERE lower(cat.category_name)=lower(p_category)
  )
  SELECT ri.rule_id, ri.tier_id, fr.rule_kind, fr.material_1_expression,
         fr.material_2_expression, result.card_name, ri.operand_expression
  FROM relevant_rule_tiers rel JOIN rule_index ri
    ON ri.rule_id=rel.rule_id AND ri.tier_id IS NOT DISTINCT FROM rel.tier_id
  JOIN fusion_rules fr USING (rule_id)
  LEFT JOIN general_fusion_rules gfr ON gfr.tier_id=ri.tier_id
  LEFT JOIN exact_fusion_rules efr ON efr.rule_id=ri.rule_id
  JOIN cards result ON result.card_id=COALESCE(gfr.result_card_id,efr.result_card_id)
  ORDER BY fr.source_order, gfr.tier_order NULLS FIRST, ri.operand_position;
$$;

CREATE OR REPLACE FUNCTION find_rule_exceptions(p_category text)
RETURNS TABLE(tier_id smallint, material_1 text, material_2 text,
              expected_result text, actual_result text)
LANGUAGE sql STABLE AS $$
  SELECT DISTINCT v.tier_id,v.material_1,v.material_2,v.expected_result,v.actual_result
  FROM v_rule_conflict_pairs_detailed v
  JOIN cards a ON a.card_name=v.material_1
  JOIN cards b ON b.card_name=v.material_2
  JOIN categories cat ON lower(cat.category_name)=lower(p_category)
  JOIN card_categories cc
    ON cc.category_id=cat.category_id AND cc.card_id IN (a.card_id,b.card_id)
  ORDER BY v.tier_id,v.material_1,v.material_2;
$$;

CREATE OR REPLACE FUNCTION find_equip_compatibility(p_card_name text)
RETURNS TABLE(query_card text, relationship text, other_card_id smallint, other_card_name text)
LANGUAGE sql STABLE AS $$
  SELECT p_card_name, 'equips', v.equipped_card_id, v.equipped_card
  FROM v_equip_compatibility_detailed v
  WHERE lower(v.equip_card)=lower(p_card_name)
  UNION ALL
  SELECT p_card_name, 'equipped by', v.equip_card_id, v.equip_card
  FROM v_equip_compatibility_detailed v
  WHERE lower(v.equipped_card)=lower(p_card_name)
  ORDER BY 2,4;
$$;


