  IF EXISTS (SELECT 1 FROM qa_checks WHERE NOT passed) THEN
    RAISE EXCEPTION 'YFM validation failed: %',
      (SELECT string_agg(check_name || ' expected=' || expected_value ||
                         ' actual=' || actual_value, '; ')
       FROM qa_checks WHERE NOT passed);
  END IF;
